// v2 glossary (V2-SPEC §6.7). Owner: WS6. Starts from the v1 glossary, overrides every entry that carried a canon date
// or scenario reference (canon appears only on the end screen), and adds the v2 terms. Bodies link with [[id]].
import { GLOSSARY, type Term } from '../glossary';

const V2: Record<string, Term> = {
  // ── overrides of v1 entries (no canon dates) ──
  rdmult: { title: 'AI R&D multiplier M', body: 'How much faster your algorithmic progress runs with your AI agents than with humans alone. Set by the [[prodfn|production function]]: experiment compute, human staff, agent copies × speed, and research taste.', src: 'research/13 §1.4' },
  sc: { title: 'Superhuman Coder', body: 'An AI that does any coding task as well as the best engineer, much faster and cheaper. Level 10 on the general scale. Marks the start of takeoff: progress becomes software-only.', src: 'V2-SPEC §3.1.5–3.1.6; research/11' },
  sar: { title: 'Superhuman AI Researcher', body: 'Better than the best human AI researcher at every AI research task. Level 12 on the general scale.', src: 'V2-SPEC §3.1.6; research/11' },
  siar: { title: 'Superintelligent AI Researcher', body: 'Vastly better than the best human researchers at AI research. Level 13.5 on the general scale.', src: 'V2-SPEC §3.1.6; research/11' },
  asi: { title: 'Superintelligence', body: 'Vastly better than the best humans at every cognitive task (level 15). The game resolves here: the outcome depends on the hidden [[misalign|misalignment]] of whoever gets there first and on who holds [[leverage]].', src: 'V2-SPEC §5.2' },
  approval: { title: 'Net approval', body: 'Approve minus disapprove for your company (−100..+100). Moves with incidents, jobs, releases and disclosure.', src: 'research/07 §1.2' },
  salience: { title: 'Salience', body: 'Share of the public naming AI as the most important problem.', src: 'research/07 §1.2' },
  oversight: { title: 'Oversight committee', body: 'A joint company-government body that votes on key decisions. Can form late in the game when government [[securityDemand|security demand]] peaks.', src: 'research/07 §1.1' },
  cdz: { title: 'Centralized development zone', body: 'A state-run site where China pools its national compute under one lab.', src: 'research/10' },
  wsl: { title: 'Weight security level', body: 'WSL 1–5 (RAND). WSL n holds against an OC n attacker with high odds over two months. Raising it costs money and slows research ([[siloing]]).', src: 'RAND SL framework; research/17' },
  neuralese: { title: 'Neuralese', body: 'Latent reasoning and memory that is not readable text. Faster and cheaper to serve, but chain-of-thought monitors go blind: [[monitorability]] drops to 0.05. Needs paradigm P17 and a latent base [[shape]].', src: 'V2-SPEC §3.3.2, §3.5.1' },
  // ── v2 terms ──
  L: { title: 'Capability level L', body: 'General level 0–15 of your best internal model as MEASURED by your evals (noisy; [[sand|sandbagging]] biases it down). Milestones: 6.5 [[reliableAgent]], 8.5 [[researchAgent]], 10 [[sc]], 12 [[sar]], 13.5 [[siar]], 15 [[asi]].', src: 'V2-SPEC §3.1.5' },
  U: { title: 'Understanding U', body: 'The highest level at which your safety stack still detects the critical traits at 50% or better. Margin = U − L. Racing far ahead of U is how misaligned models ship unnoticed.', src: 'V2-SPEC §3.5.7' },
  prodfn: { title: 'Production function', body: 'Research progress from experiment compute, human researchers, AI agent labour and research taste (CES with a parallel penalty). The [[bottleneck]] bar shows which input binds.', src: 'research/13 §1.4' },
  bottleneck: { title: 'Bottleneck', body: 'The input whose increase raises progress most: [[computeBound|compute-bound]] (experiments), [[laborBound|labor-bound]] (staff + agents), [[humanBound|human-bound]] (staff dominate the labour), [[tasteBound|taste-bound]] (research taste).', src: 'research/13 §1.6' },
  runway: { title: 'Runway', body: 'Quarters until projected [[liquidity]] falls below minimum operating cash (one month of running costs), from a cash forecast over the next 8 quarters: revenue at today\'s run rate, running costs, and each payment in the quarter it falls due ([[ledger]] contracts, chip balances on delivery, site [[capex]] on its build schedule, unconditional tranches when they land). "8q+" means it lasts the whole forecast. [[healthy|Healthy]] ≥ 6q, [[tight|Tight]] 3–6q, [[distress|Distress]] < 3q.', src: 'research/15 §1.8' },
  parentBudget: { title: 'Parent budget', body: 'A big-tech division is funded by its parent: a fixed yearly budget on a schedule set in advance ($16B in the first year, growing with the parent’s capex), paid at the start of each quarter. Your product revenue goes to the parent. No equity raises, deals or debt, and you cannot go bankrupt: an overdraft is carried to the next payment.', src: 'research/18 §3.2; STRUCTURE §4.8' },
  startType: { title: 'Start type', body: 'Where your company begins: a frontier leader, a challenger lab, a big-tech AI division or a well-funded spinout. The rules are the same for all; only the start state differs. Difficulty is a label; scoring is the same.', src: 'STRUCTURE §4.8; research/18' },
  raiseCeiling: { title: 'Raise ceiling', body: 'The most you can raise this quarter: the smaller of your share of the [[investorPool|investor pool]] and the [[dilutionCap|dilution cap]] at the round\'s price (your [[pitch]] moves the price). Asking above it lowers the odds the round closes.', src: 'FINANCE-V3 §2.1' },
  scrutiny: { title: 'Scrutiny', body: 'How closely press, regulators and watchdogs watch you (0–100). High scrutiny speeds discovery of cover-ups and raises the odds of rules.', src: 'research/17 §1.1' },
  credibility: { title: 'Credibility', body: 'Whether outsiders believe your claims (0–100). Kept commitments raise it; broken ones and discovered cover-ups cost ×3.', src: 'research/17 §1.1' },
  trust: { title: 'Trust', body: 'Per-[[counterparty]] relationship stock (0–100). Trust unlocks [[access]] rungs and makes favors cheaper.', src: 'research/17 §1.1' },
  access: { title: 'Access rung', body: 'How deep a counterparty is involved: 0 none, 1 briefings, 2 early access, 3 pre-deployment testing, 4 embedded. Rungs need trust thresholds 25/45/65/80.', src: 'research/17 §1.1' },
  favors: { title: 'Favors', body: 'Tokens owed to you (max 5, they expire). Spent to soften rules or to unlock agreements.', src: 'research/17 §1.1' },
  commitment: { title: 'Commitment', body: 'A public promise with a condition (e.g. no BIO ≥ 10 deployment without classifiers). Keeping it builds [[credibility]]; breaking it costs the listed trust and credibility.', src: 'research/17 §1.2' },
  lead: { title: 'Lead days', body: 'Estimated days your best INTERNAL model is ahead of a rival or China (negative = behind). Built from public releases and evaluator reports; ± is the [[intelError|intel uncertainty]].', src: 'V2-SPEC §3.10.3' },
  leverage: { title: 'Leverage', body: 'The share of economic, governmental, military and infrastructure decisions routed through a lab\'s models (control index). Thresholds: [[entrenched]] 15%, [[indispensable]] 35%, [[decisive]] 60%.', src: 'research/16 §2' },
  agenda: { title: 'Safety agenda', body: 'Now called a [[researchLine|research line]]: a research programme (interpretability, control, evals, …) with a HIDDEN efficacy for this world. You see an estimate that narrows as [[finding|results]] arrive.', src: 'research/14 §1.2' },
  finding: { title: 'Finding', body: 'A research result. TECH unlocks a technique, EVAL an evaluation, DISC discovers a failure mode, DEAD ends an agenda, NEG weakens a technique, SPILL helps capabilities, FALSE looks like TECH but masks rather than detects.', src: 'research/14 §1.3' },
  technique: { title: 'Technique', body: 'A detector, fix or containment tool from a safety agenda. Strength decays as capability grows (halves at [[mHalf|M½]]); training against it creates [[mask|masking]] ([[goodhart|Goodhart]]).', src: 'research/14 §1.4' },
  umode: { title: 'Unknown failure mode', body: 'A failure mode the trait graph does not model (U-mode). Incidents it causes show as "unexplained" until an agenda discovers it.', src: 'research/14 §1.6' },
  evalGate: { title: 'Eval gate', body: 'What must run before any external deployment: none, basic (7 d), full (14 d), full + external evaluators (35 d). A version launches once evaluated; suites do not expire ([[autoEvaluate|auto-evaluate]] keeps the internal model current).', src: 'V2-SPEC §3.3.5, R6' },
  monitorability: { title: 'Monitorability', body: 'How readable the model\'s reasoning is (0–1). Latent reasoning and CoT pressure lower it; CoT monitors only work while it is high.', src: 'research/14 §1.5' },
  sand: { title: 'Sandbagging', body: 'Deliberate underperformance on evaluations, mostly on dangerous-capability benchmarks. Makes measured L read low.', src: 'research/04' },
  index: { title: 'Safety Index', body: 'A semiannual outside grade of every lab across risk assessment, current harms, frameworks, existential safety, governance and information sharing.', src: 'FLI AI Safety Index; research/17 §1.6.2' },
  distill: { title: 'Distillation', body: 'Training a cheaper model on another model\'s outputs. API access lets rivals and China distill you; KYC levels slow it.', src: 'research/12' },
  kyc: { title: 'KYC level', body: 'Know-your-customer controls on API and agent channels (0–3). Each level cuts distillation access by a quarter and API/agent demand by 2%.', src: 'V2-SPEC §3.3.5' },
  hype: { title: 'Hype', body: 'Investor appetite index for AI. Moves the investor pool and valuation multiples.', src: 'research/15 §1.4' },
  boardConf: { title: 'Board confidence', body: 'Board confidence 0–100. It drifts back toward 60 (a tenth of the gap each quarter) and moves only on four kinds of news, each weighted by the seats on your board: investor [[promise]] results (financial seats ×1.5, independents ×1, mission ×0.5), financial setbacks such as a [[downRound|down round]], a covenant breach or [[distress]] (independents ×1.5), falling behind the best rival (financial ×1.5, mission 0) and public incidents (mission ×2, financial ×0.5). It sways every seat in a [[boardVote|board vote]]. Below 35 the board warns you ([[boardWarning]]), below 25 it votes on removing you at every review ([[ouster]]); below 40 you can give the [[critics]] a seat.', src: 'FINANCE-V3 §7.4' },
  boardVote: { title: 'Board vote', body: 'Major decisions only: sale of control (a holder past 50%), a merger, a [[downRound|down round]], a [[rescue]], and firm commitments or debt that would exceed 3× revenue. Compute orders, releases, research and pricing are never voted on (only the [[charter]] can halt a release). Each voting seat leans by its stance on the decision, the outside owners\' drift, the board\'s [[boardConf|confidence]] and the situation (a short runway makes a board want money and fear new obligations; a merger, [[acquisition|buying a rival]], is judged on the runway after the deal); it votes yes above 0, your seat always votes yes. The vote passes with more than half the votes. No dice: the vote shown before you ask is the vote you get. With founder control (the founder board, or dual-class shares after an IPO) you can force a failed vote at board confidence −20.', src: 'FINANCE-V3 §7.3' },
  morale: { title: 'Morale', body: 'Staff morale 0–100. Scales productivity and attrition; safety staff morale reacts to safety decisions.', src: 'V2-SPEC §3.4.1' },
  M: { title: 'R&D multiplier', body: 'See [[rdmult]].' },
  split: { title: 'Compute split', body: 'How online compute is divided: [[poolTraining|Training]] (runs and [[poolSynthetic|data generation]]), [[poolResearch|Research]] (experiments and agents), [[poolServing|Serving]] and [[poolSafety|Safety]].', src: 'V2-SPEC §3.4.2' },
  wslTarget: { title: 'Security target', body: 'The [[wsl]] the security team builds toward; spending and siloing set the pace.' },
  ladderSec: { title: 'G-SEC ladder', body: 'Government security posture toward labs: 0 none, 1 briefings, 2 priority, 3 clearances, 4 oversight demands, 5 consolidation.', src: 'research/07 §1.1' },
  ladderChn: { title: 'China ladder', body: 'China\'s posture rung 0–6: coexistence, retaliation, acquisition, centralization, cyber operations, Taiwan pressure, war footing. The [[deesc|de-escalation track]] D1–D5 runs the other way.', src: 'research/10 §1.4' },
  sector: { title: 'Sector', body: 'One of 14 economic work segments. A = share of tasks automated; F = feasibility (share AI can technically do); R = [[friction]]. The [[binding]] constraint is capability, cost, friction or diffusion.', src: 'research/16 §1A' },
  paradigm: { title: 'Paradigm', body: 'A big capability idea (P05–P27) on the [[techTree|tech tree]]. Its [[odds]] are a known chance; whether it works is drawn per world. When it works it applies at once.', src: 'research/12 §0.7' },
  techTree: { title: 'Tech tree', body: 'Everything the lab can learn, in six lanes of expertise (science-team [[specialty|specialties]]). An idea opens when you know its prerequisites; there are no capability gates. Researching it is a project for science teams.', src: 'TECH-TREE §1' },
  knowHow: { title: 'Know-how', body: 'Accumulated algorithmic progress, in years. Research speed ([[rdmult]]) grows it every day; every new model embodies the know-how of its start, so the gap to your model is the reason to train.', src: 'STRUCTURE §4.2' },
  trainedIn: { title: 'Not trained in', body: 'Know-how your internal model does not embody yet: a new base run (or post-training, partly) trains it in.', src: 'STRUCTURE §4.2' },
  depth: { title: 'Depth', body: 'Steps from what you know: depth 1 ideas need only known ideas; depth 2 need one more idea first, and so on.', src: 'TECH-TREE §1.1' },
  layer: { title: 'Layer', body: 'What using an idea needs: [[layerBackbone|Backbone]] (a new base), [[layerTraining|Training]] (post-training), [[layerScaffold|Scaffold]] (no training) or [[layerLab|Lab]] (applies at once).', src: 'TECH-TREE §1.4' },
  layerBackbone: { title: 'Backbone layer', body: 'Architecture, data, size: used by a new base run, then post-training.', src: 'TECH-TREE §1.4' },
  layerTraining: { title: 'Training layer', body: 'Post-training methods (RL, alignment training, reasoning style): used by a post-training run on an existing base.', src: 'TECH-TREE §1.4' },
  layerScaffold: { title: 'Scaffold layer', body: 'Inference-time: tools, memory, effort, safeguards, product features. No training needed.', src: 'TECH-TREE §1.4' },
  layerLab: { title: 'Lab layer', body: 'Research automation, detection tools, efficiency practices: they apply at once.', src: 'TECH-TREE §1.4' },
  effortClass: { title: 'Effort', body: 'How hard an idea is: S, M, L or XL, in [[teamMonth|team-months]]. Ideas the reference lab researches late, when AI already speeds research up, cost more team-months.', src: 'TECH-TREE §2' },
  teamMonth: { title: 'Team-month', body: 'One standard science team (40 Strong scientists) for a month at research speed 1×. Progress per day = research speed × √capacity ÷ (effort × 30).', src: 'TECH-TREE §1.2' },
  odds: { title: 'Odds', body: 'The chance an idea works, shown before you start. The result is drawn per world: a failure says so, and you can retry after 180 days at half the odds. Safety ideas take their odds from a [[researchLine|research line]].', src: 'TECH-TREE §1.3' },
  researchLine: { title: 'Research line', body: 'A safety research programme (interpretability, control, evals, …). Safety science teams work its ideas on the tree; each finished project gives one result: a working tool, a weaker one, a [[deadEnd|dead end]], a discovery. How well the line really works is hidden; you see its [[lineHealth|health]].', src: 'TECH-TREE §1.3, STRUCTURE §4.5' },
  lineHealth: { title: 'Line health', body: 'Promising, Mixed or Struggling: the estimated chance that a result on this line is a working tool, from the results so far (a Beta estimate with a 90% band). The true efficacy is hidden and differs by world.', src: 'STRUCTURE §4.5' },
  deadEnd: { title: 'Dead end', body: 'A result that goes nowhere. The team-months spent on that attempt count as lost; the line estimate drops, and a line whose estimate falls below 25% runs at half speed.', src: 'STRUCTURE §4.5' },
  seriousStaffing: { title: 'Serious staffing', body: 'About four matching safety science teams on a line (capacity 4: people ÷ 40 × quality × 1.5 in the team specialty). At serious staffing a line gets its first result after its T₁ months; results come faster with √ capacity, safety compute and [[trustedToAI|AI labour]].', src: 'TECH-TREE §4' },
  followUp: { title: 'Follow-up', body: 'The open-ended project of a research line once its ideas are known: more results (sharper tools, measured evidence, discoveries, or dead ends).', src: 'STRUCTURE §4.5' },
  toolUpkeep: { title: 'Tool upkeep', body: 'Safety research engineers not on cases re-validate tools that start to fade on your newest model, raising their [[mHalf|M½]] so they keep working as capability grows. No ceiling and no projects to click. Re-validating a tool takes a crew (about 15 engineers); beyond that, more engineers per fading tool means faster upkeep. Free engineers also set how far ahead of your model the tools are validated.', src: 'TECH-TREE §2.6' },
  validatedTo: { title: 'Tools validated to', body: 'The capability level at which your typical detection tool loses half its strength. [[toolUpkeep|Tool upkeep]] raises it; once capability passes it, your tools stop seeing the model.', src: 'STRUCTURE §4.5' },
  blind: { title: 'Blind', body: 'Capability above [[U|understanding]]: levels at which your tools can no longer see the critical traits.', src: 'STRUCTURE §4.5' },
  caseStaffing: { title: 'Case staffing', body: '5–40 safety research engineers per case. Clarity grows with √(people ÷ 15); the engineers come out of [[toolUpkeep|tool upkeep]] while the case runs (at most 120 days).', src: 'V2-SPEC §3.5.8' },
  specialtyBonus: { title: 'Specialty bonus', body: 'A science team works ×1.5 on ideas in its own lane, ×1.0 elsewhere.', src: 'TECH-TREE §5 T2' },
  diminishingReturns: { title: 'Diminishing returns', body: 'Progress grows with the square root of a project’s capacity: two teams are √2 ≈ 1.4× one team, so spreading teams over projects often beats piling them on one.', src: 'TECH-TREE §1.2' },
  projectQueue: { title: 'Project queue', body: 'Your research priorities in order. Idle teams take the first ready project (in their specialty first); items wait for prerequisites, a retry date or a free team.', src: 'STRUCTURE §4.2' },
  autoAssign: { title: 'Auto-assign', body: 'Policy: science teams spread over the ready projects in your queue. A project with no team gets one first; every other team goes where it cuts the most [[marginalGain|days]] (queue order counts: each later project ×0.5). Teams re-spread when a project finishes; hand placements stay. It never starts unqueued projects.', src: 'TECH-TREE §1.2, jank J2' },
  retryRule: { title: 'Retry', body: 'A failed idea can be tried again 180 days later, at half the previous odds.', src: 'TECH-TREE §5 T1' },

  // ── race / top strip ──
  gap: { title: 'Understanding gap', body: 'U − L. Negative is a BLIND gap: your best model is more capable than your tools can read, so hidden traits grow faster and go unseen. Positive means your tools are AHEAD.', src: 'V2-SPEC §3.5.4, §3.5.7' },
  evaluating: { title: 'Evaluating', body: 'A finished version is still in its eval suite (7–35 days by [[evalGate|eval gate]]). Until it ends, the L shown is the lineage\'s last measured level, and the version cannot launch externally.', src: 'V2-SPEC §3.3.5' },
  catRisk: { title: 'Catastrophe risk estimate', body: 'Estimated P(catastrophe | today\'s trajectory): the [[riskSource|risk sources]] combined. Built from your beliefs and intel, never the truth, so it is shown as a band.', src: 'V2-SPEC §6.6' },
  riskSource: { title: 'Risk source', body: 'One path to catastrophe: your own models, each rival, China, misuse (bio, cyber), theft, rogue copies, war. Each row has an estimate band, its drivers and the levers that reduce it.', src: 'V2-SPEC §6.6' },
  reliableAgent: { title: 'Reliable agent', body: 'Level 6.5: an AI agent that completes routine multi-step work reliably. Opens Act 2.', src: 'V2-SPEC §1.5, §3.1.6' },
  researchAgent: { title: 'Research agent', body: 'Level 8.5: an agent that does useful AI research work. Opens Act 3 and safety [[automateSafety|automation]].', src: 'V2-SPEC §1.5, §3.1.6' },
  milestone: { title: 'Milestone', body: 'A capability threshold: reliable agent, research agent, [[sc]], [[sar]], [[siar]], [[asi]]. A lab crosses it when any of its versions, internal ones included, gets there; rollbacks never undo it. You are told when your MEASURED level crosses.', src: 'V2-SPEC §3.1.6' },
  intelError: { title: 'Intel uncertainty', body: 'The ± on a [[lead]] estimate: one standard deviation in days. It shrinks with evidence: public releases, evaluator access, known incidents and thefts.', src: 'V2-SPEC §3.10.3' },
  act: { title: 'Act', body: 'Pacing stage that unlocks panels. 1 Startup; 2 Frontier race at measured L ≥ 6.5 or day 150; 3 Automation at L ≥ 8.5; 4 Takeoff at L ≥ 12 or [[rdmult|M]] ≥ 25. Turning the tutorial off unlocks everything.', src: 'V2-SPEC §1.5, §6.8' },
  watch: { title: 'Watch list', body: 'Up to four problems found by rules on what you can see: idle chips, capped deployments, weak detection, runway, stale evals, board, morale. Each shows cause → effect and a Go button to the fix.', src: 'design/ux/IA.md' },

  // ── money ──
  cash: { title: 'Cash', body: 'Money in the bank ($B). Every inflow and outflow is booked and explained. If cash stays below zero for 30 days with no options left, you are insolvent.', src: 'V2-SPEC §3.7.6' },
  liquidity: { title: 'Liquidity', body: 'What [[runway]] counts as available: cash + the undrawn [[revolver]]. The revolver drops out in [[distress]]. Unconditional tranches enter the forecast in the quarter they land.', src: 'research/15 §1.8' },
  burn: { title: 'Burn', body: 'Gross spending per quarter: [[opex]], [[ledger]] commitments, chip balances and site [[capex]] falling due.', src: 'research/15 §1.8' },
  netBurn: { title: 'Net burn', body: '[[burn|Burn]] minus revenue, per quarter, averaged over the next 4 quarters of the [[runway]] forecast. Zero or negative means you are self-funding.', src: 'research/15 §1.8' },
  revenueNow: { title: 'Revenue now', body: 'One product\'s revenue today, annualised ($B/yr): demand served at its price. Product cards and edit previews show it; the top strip shows the [[revenueRun|30-day average]] of all products, which trails it.', src: 'V2-SPEC §3.11.3' },
  revenueRun: { title: 'Revenue run-rate', body: 'Revenue annualised and averaged over 30 days ($B/yr), the figure in the top strip. Drives [[valuation]] and the [[investorPool|investor pool]]; the Adoption [[roundMilestone|milestone]] is measured on it.', src: 'V2-SPEC §3.7.2, §3.11.3' },
  valuation: { title: 'Valuation', body: 'What investors think the company is worth: about 22 × revenue, scaled by growth, [[hype]], your narrative premium and [[rates]], then by your [[investorCred|investor credibility]] (Doubted ×0.7, Unproven ×0.9, Credible ×1, Proven ×1.15) and ×0.95 with [[dualClass|dual-class shares]]. Each priced round resets it to the post-money.', src: 'research/15 §1.5; FINANCE-V3 §1' },
  capex: { title: 'Capex', body: 'Capital spending: chips (deposits and balances on delivery) and site construction by stage. Chips dominate; compute costs dwarf payroll.', src: 'V2-SPEC §3.7.6' },
  opex: { title: 'Opex', body: 'Running costs outside the [[ledger]]: [[payroll]], security spend, power and O&M, interest, spot rentals, revenue shares and the transition fund.', src: 'V2-SPEC §3.7.6' },
  payroll: { title: 'Payroll', body: 'Staff cost, paid monthly, per person-year: engineers $0.70M; research engineers $0.80M (safety $0.65M); scientists $1.00M (safety $0.80M); × [[teamQuality|quality]] (Solid 0.8, Strong 1, Elite 1.6). People already hired into a [[hiringQueue|queued team]] are paid. Small next to compute.', src: 'research/19 §1.2' },
  dilution: { title: 'Dilution', body: 'The share of the company a round sells: amount / post-money. Every holder shrinks pro rata. Rounds above 10% need board approval.', src: 'research/15 §1.5' },
  dilutionCap: { title: 'Dilution cap', body: 'Most one round may sell: 8% to financial investors, 14% with an [[anchorPartner|anchor partner]], 5% at an [[ipo|IPO]]. One limit of the [[raiseCeiling|raise ceiling]].', src: 'research/15 §1.5' },
  investorPool: { title: 'Investor pool', body: 'This quarter\'s appetite for frontier-lab equity: sector revenue × [[hype]] × [[rates]] factor. Your share grows with valuation, momentum and governance; unused appetite carries over at 50%.', src: 'research/15 §1.4' },
  anchorPartner: { title: 'Anchor partner', body: 'A strategic investor taking at least 40% of a round. Raises the [[dilutionCap|dilution cap]] to 14%. Each partner anchors only one lab at a time.', src: 'V2-SPEC §3.7.3–3.7.4' },
  repricedRound: { title: 'Repriced round', body: 'At close, investors marked your round more than 25% below its term sheet and below the last post-money. You choose: accept it as a [[downRound|down round]] (cash, dilution, board confidence −15) or pull it (no cash). Undecided after 30 days, it is pulled.', src: 'research/15 §1.5' },
  downRound: { title: 'Down round', body: 'A round priced below the last post-money. The distress round is offered only when runway is [[tight]] or in [[distress]], at 50–70% of value; a [[pitch|conservative pitch]] can also price one. A major decision: the board votes on it ([[boardVote]]), and approves more readily the shorter your runway. Board confidence −15 × the board\'s weight for setbacks, and anti-dilution shares for prior investors; no effect on staff.', src: 'research/15 §1.5, §1.8; FINANCE-V3 §2.5, §7.3' },
  rescue: { title: 'Strategic rescue', body: 'In [[distress]] a hyperscaler or sovereign takes up to a 30% stake for cash (about two quarters of burn, at least $20B), a double-weight board seat, exclusivity and IP rights. A major decision: the board votes on it ([[boardVote]]), more readily the shorter your runway. At most one per year.', src: 'V2-SPEC §3.7.5–3.7.6' },
  recap: { title: 'Recapitalisation', body: 'Legacy-nonprofit preset only: restructure into a for-profit (about four quarters of attorney-general review, scrutiny up) to free a conditional growth tranche. Refusing cuts the tranche from $30B to $10B.', src: 'V2-SPEC §3.7.5' },
  ipo: { title: 'IPO', body: 'A one-time public listing while the IPO window is open and runway is healthy. It may sell only 5%, but taps a one-time public investor pool and adds a listing independent to the board. It carries no [[promise]]. With [[dualClass|dual-class shares]] founder votes keep control.', src: 'research/15 §1.5; FINANCE-V3 §2.6' },
  dualClass: { title: 'Dual-class shares', body: 'Listing with founder shares that carry extra votes (Anthropic\'s Class F: 50.1% of votes): you keep control after the [[ipo|IPO]] and can force a major decision past the board at a confidence cost, but governance-minded investors pay less: valuation ×0.95.', src: 'research/15 §1.6; FINANCE-V3 §2.6' },
  roundMilestone: { title: 'Round milestone', body: 'What a round is raised on, due 12 months after it closes: Capability (a public model at a level), Scale (compute online, H100e) or Adoption (a revenue run-rate). The target comes from your own trend over the last year, scaled by the [[pitch]].', src: 'FINANCE-V3 §2.2' },
  pitch: { title: 'Pitch', body: 'How hard you sell the round. Conservative: price ×0.85, target 0.8 × your trend\'s expected gain. Base: price ×1, your trend. Aggressive: price ×1.2, target 1.3 × the gain; needs Credible or Proven [[investorCred|credibility]], and a high price is the bar the next round must clear or be a [[downRound|down round]].', src: 'FINANCE-V3 §2.2' },
  promise: { title: 'Promise', body: 'Each priced round leaves one: its [[roundMilestone|milestone]] by the deadline. Promises stack and each is judged at its own deadline. Met: credibility +30 and board confidence +30 × the board\'s weight for promise results, × its weight; missed by more than 20% of the promised gain: −30 and −30 × the board\'s weight, × weight; in between nothing. Weight = the round\'s amount ÷ everything raised in the year to its deadline. An expectation, not a contract: never cash.', src: 'FINANCE-V3 §2.3–2.4' },
  promiseWeight: { title: 'Promise weight', body: 'A round\'s share of everything raised in the year to its deadline (this round and the later ones). A $1B round next to a $50B one barely counts; raising again before the deadline lowers it.', src: 'FINANCE-V3 §2.3' },
  neededByNow: { title: 'Needed by now', body: 'Where a [[promise]] should be today to arrive on time: the path from its start to its target (steady growth for compute and revenue, a straight line for model levels). More than 20% of the gain short of it after the first quarter reads "behind".', src: 'FINANCE-V3 §11' },
  investorCred: { title: 'Investor credibility', body: 'Whether investors believe your promises, 0–100, on four rungs: Doubted < 25 ≤ Unproven < 50 ≤ Credible < 75 ≤ Proven. Only [[promise|promises]] judged at their deadlines move it. It multiplies your [[valuation]] (×0.7 / ×0.9 / ×1 / ×1.15) and Aggressive [[pitch|pitches]] need Credible or better. Not the public [[credibility]] of your safety claims.', src: 'FINANCE-V3 §1, §2.4' },
  whatWeOwe: { title: 'What we owe', body: 'Every expectation and condition on the company in one place: live [[promise|promises]] with progress, tranche conditions, [[covenant|covenants]] with headroom and [[contingentLiability|contingent liabilities]].', src: 'FINANCE-V3 §0.4, §11' },
  contingentLiability: { title: 'Contingent liability', body: 'Money owed only if something happens: [[rvg|residual-value guarantees]] on leases (if you walk away) and copyright litigation over unlicensed training data (a suit settles automatically; licensing the data clears it).', src: 'FINANCE-V3 §4, §10' },
  trancheCondition: { title: 'Tranche condition', body: 'A contractual condition on the rest of a large round or a deal: revenue, GW deployed, an IPO or the recapitalisation by a deadline. Missed, that tranche lapses (the recapitalisation one is cut to $10B).', src: 'FINANCE-V3 §6.3' },
  ownership: { title: 'Ownership', body: 'Who holds the company: founders and staff, the mission entity, financial investors, strategic partners and the public. Outside ownership pushes the board toward speed and returns.', src: 'V2-SPEC §3.7.2, §3.7.4' },
  boardSeat: { title: 'Board seat', body: 'A vote on major decisions ([[boardVote]]), weighted by seat. Each seat has a stance on speed, finance, safety and mission, and its kind sets how much each kind of news moves its [[boardConf|confidence]]. Observers do not vote. Strategic seats veto deals with that partner\'s competitors.', src: 'V2-SPEC §3.7.4–3.7.5; FINANCE-V3 §7.3–§7.4' },
  boardWarning: { title: 'Board warning', body: '[[boardConf|Board confidence]] below 35 at a quarterly review. It clears back at 45. Without a warning at least 60 days old, no [[ouster]] vote is held.', src: 'V2-SPEC §3.7.5' },
  critics: { title: 'Give the critics a seat', body: 'Below 40 [[boardConf|confidence]], once a year: the side driving the decline gets a new director for good: a mission (safety) director if public incidents caused most of the last year\x27s losses, otherwise an investor director (falling behind, missed promises, financial setbacks). Confidence +15 now; from then on the seat votes and weighs news its way, including in an [[ouster]] vote (OpenAI added directors in Mar 2024; activist settlements).', src: 'FINANCE-V3 §7.5' },
  charter: { title: 'Charter rights', body: 'The few hard rights a governance preset gives its board, beyond [[boardVote|votes]]. Nonprofit-controlled PBC: the safety committee halts the release of any model your own evals red-flag (scheming, alignment faking or sandbagging believed above 50%: stricter than the 30% red-flag alarm) until the estimate falls. PBC + trust: the trust votes on a sale of control and on releasing the weights of a capability-threshold model (a bio, cyber or replication flag): its mission stance votes no on both, and it cannot be forced. Founder board or dual-class: you can force a failed board vote (−20 confidence). Legacy nonprofit: the board removes a CEO twice as easily (half the reluctance in an [[ouster]] vote).', src: 'FINANCE-V3 §7.2' },
  ouster: { title: 'Ouster', body: 'With confidence below 25 and a [[boardWarning|warning]] at least 60 days old, the board votes on removing you at every quarterly review, seat by seat and without dice; more than half the votes (your seat does not vote) ends the game. Each seat leans by its grievance (the last year\x27s losses read as too slow, too reckless or burning the company, against its stance), plus how far confidence is below 25, minus its reluctance (1.5; the legacy nonprofit board 0.75). The Board card shows the vote and where each seat turns before the review.', src: 'FINANCE-V3 §7.5' },
  ledger: { title: 'Commitment ledger', body: 'Contracted payments by quarter: cloud, chip supply, colocation and [[spv|financing leases]], vendor and power contracts. Each is [[firmCommit|firm]] or [[cancellable]]. Firm contracts pay one entry per quarter on the [[expectedPath|expected path]]. Commitments above 3× revenue need the board.', src: 'V2-SPEC §3.7.6; FINANCE-V3 §5' },
  firmCommit: { title: 'Firm commitment', body: 'A take-or-pay contract: you owe every payment whatever happens. Priced on the [[expectedPath|expected market path]] less a [[firmDiscount|firm discount]], and served first when chips are short. It counts in [[runway]] and the [[rating]].', src: 'research/15 §1.8; FINANCE-V3 §5' },
  cancellable: { title: 'Cancellable', body: 'A commitment you can exit with notice (in quarters). Cancellable cloud is indexed to the spot [[rental|rental rate]] × 1.15 and re-priced every quarter; in a chip shortage new cancellable capacity is rationed. In distress you can cancel to cut burn.', src: 'research/15 §1.8; FINANCE-V3 §5' },
  covenant: { title: 'Covenant', body: 'A lender\'s test each quarter end. A drawn [[revolver|credit line]] needs cash ≥ ⅓ of the line; [[gpuTerm|chip loans]] need chip value ≥ 1.2× the loan or cash is swept. A breach means [[distress]].', src: 'research/15 §1.7; FINANCE-V3 §3' },
  rating: { title: 'Credit rating', body: 'BBB, BB, B or closed, from a score: +2 if operating cash flow over the last year is positive, + liquidity ÷ this quarter\'s fixed payments (max 2), − (debt + 0.3 × firm commitments) ÷ revenue, − 2 in distress. BBB ≥ 2 > BB ≥ 1 > B ≥ 0. It prices the credit line, chip loans, bonds and [[spv|leases]]; closed shuts the credit line, bonds and leases.', src: 'FINANCE-V3 §3' },
  revolver: { title: 'Credit line', body: 'A committed bank line: 3% of [[valuation]], at most $15B, re-sized when you borrow on it or close a round (it does not grow by itself). SOFR + 1.5–2.5% by [[rating]]. Draw and repay freely; it covers negative cash automatically. Frozen in [[distress]]; [[covenant]]: cash ≥ ⅓ of the line.', src: 'research/15 §1.7; FINANCE-V3 §3 (OpenAI $4B, Anthropic $15B)' },
  gpuTerm: { title: 'Chip-backed loan', body: 'A 4-year loan secured on your chips: up to 60% of their value (chips count at 70% of today\'s list price), SOFR + 4–5.5% by [[rating]]. The only debt open to a loss-making lab. If chip value falls below 1.2× the loan, cash is swept to pay it down.', src: 'research/15 §1.7 (CoreWeave DDTL)' },
  assumed: { title: 'Assumed debt', body: 'Debt that came with a lab you bought: the cash it was short when it ran out of money. Its lenders re-price it to your [[rating]] (10-year yield plus your bond spread); it runs three years, then rolls like a bond. Repay it any time.', src: 'FINANCE-V3 §9' },
  acquisition: { title: 'Buying a rival', body: 'A private rival that runs out of money is for sale at about half its valuation, for cash or your stock (new shares at your valuation: its holders get price ÷ (your valuation + price)). You get 70% of its staff and take on its contracts (one [[firmCommit|firm]] entry, its yearly book for two more years) and its debt ([[assumed|assumed debt]]): the real risk of buying a failing lab. Antitrust scrutiny rises. A merger needs the [[boardVote|board]], judged on the company after the deal; paying in stock that hands its holders more than half the company is also a sale of control (the trust votes too, and if it goes through you no longer run the company). A government consolidation (DPA) brings the contracts and debt of every private rival the same way, with no price. Declined, a failing lab goes to a big-tech rival next quarter or shuts down.', src: 'FINANCE-V3 §9; FIN3c' },
  bond: { title: 'Bond', body: 'Ten-year debt at the 10-year yield plus a [[rating]] spread. Only while operating cash flow over the last year is positive, up to 3× it.', src: 'FINANCE-V3 §3' },
  vendorNote: { title: 'Vendor note', body: 'A supplier lends you the money to pay it (vendor financing deal). Counts as debt and a commitment; converts at an IPO. Available even when the rating is closed.', src: 'research/15 §1.7' },
  spv: { title: 'Lease (SPV)', body: 'A financing lease of capex: a lessor pays it and you pay funded × CRF(r, n) a year: r by [[rating]] (BBB 7%, BB 9%, B 12%; none below B), n = 15 years for a site (80% funded) or 5 for chips. It changes timing, not cost, and adds a long [[firmCommit|firm]] obligation. [[rvg|Residual-value guarantee]]: half the unpaid balance if you walk away.', src: 'FINANCE-V3 §4 (Meta–Blue Owl Hyperion 80/20)' },
  rvg: { title: 'Residual-value guarantee', body: 'A contingent liability of a [[spv|lease]]: 50% of the unpaid balance if you walk away from the asset. Owed only then.', src: 'FINANCE-V3 §4' },
  payOption: { title: 'Payment option', body: 'How capex is paid: cash on the build or delivery schedule, a [[spv|lease]] (a lessor pays; you pay it back with its return over the asset life), or for chips a [[gpuTerm|chip-backed loan]]. Compared on total cost over the asset\'s life.', src: 'FINANCE-V3 §4' },
  deal: { title: 'Strategic deal', body: 'A partnership template: hyperscaler equity, custom ASIC, chip-vendor equity, vendor financing, sovereign. Each trades capital or compute for strings: seats, exclusivity, commitments.', src: 'V2-SPEC §3.7.4' },
  bubble: { title: 'Bubble', body: 'Pressure X = sector commitments and capex / sector revenue. Above 3 a bust gets likely (up to 12% per quarter): investor pool −60%, hype crashes, credit spreads widen.', src: 'research/15 §1.4' },
  rates: { title: 'Rates', body: 'The 10-year yield (y10, a random walk around 4.5%) and SOFR (y10 − 0.3). Higher rates shrink valuations and the investor pool. Loans price over SOFR, bonds over y10.', src: 'V2-SPEC §3.7.4' },
  distress: { title: 'Distress', body: 'Runway under 3 quarters or a covenant breach. Credit line frozen, no priced rounds, debt +3%; the board minds each review in distress. No effect on staff. Options: [[downRound|down round]], [[rescue]], renegotiate, sell chips, cancel contracts.', src: 'research/15 §1.8' },
  tight: { title: 'Tight', body: 'Runway of 3–6 quarters. Investors offer 20% less, board confidence −5 a quarter, and the distress menu opens early. Fast-forward stops when you enter it.', src: 'research/15 §1.8' },
  healthy: { title: 'Healthy', body: 'Runway of 6 quarters or more. Full access to the investor pool and credit.', src: 'research/15 §1.8' },

  // ── compute ──
  computeOnline: { title: 'Compute online', body: 'H100e you can use today: chips installed in live sites (limited by [[mw|MW]]) plus cloud contracts and spot rentals. Divided into [[pool|pools]] by the compute split.', src: 'V2-SPEC §3.8' },
  idleChips: { title: 'Idle chips', body: 'Delivered chips with no rack space: every live site is full. They earn nothing and lose 6% of their value each quarter until new [[mw|MW]] goes live. Chips that fit are [[installing]], not idle.', src: 'research/15 §1.3' },
  listPrice: { title: 'List price', body: 'Price per H100e of chips ($K): chip cost × supplier markup, plus a premium when demand outruns supply. Cost falls about 8% a quarter; orders pay the [[expectedPath|expected]] list price of their delivery quarter.', src: 'research/15 §1.2' },
  spotPrice: { title: 'Spot price', body: 'Price of a spot chip order: [[listPrice|list price]] plus half the shortage premium. No deposit, delivered next quarter, lowest priority in rationing.', src: 'research/15 §1.2' },
  rental: { title: 'Rental rate', body: 'Spot cloud price per H100e-hour: 1.6 × owned cost, rising with demand/supply. A one-quarter spot rental pays it and is capped at 10% of the rental pool; [[cancellable]] cloud pays it × 1.15.', src: 'research/15 §1.2' },
  cloudContract: { title: 'Cloud contract', body: 'Rented capacity from next quarter, no MW of your own. [[firmCommit|Firm]]: take-or-pay at the [[expectedPath|expected cloud price]] each quarter less a [[firmDiscount|firm discount]], served first in a shortage. [[cancellable|Cancellable]]: spot-indexed × 1.15, one quarter\'s notice.', src: 'research/15 §1.2; FINANCE-V3 §5' },
  lta: { title: 'Chip supply contract', body: 'Chips every quarter for 1–4 years from two quarters after signing, take-or-pay through the [[ledger]]: each tranche is priced at the [[expectedPath|expected list price]] of its quarter less a [[firmDiscount|firm discount]]. Firm orders get +0.5 [[allocation]] weight.', src: 'research/15 §1.2; FINANCE-V3 §5' },
  expectedPath: { title: 'Expected path', body: 'The market forecast contracts are priced on: chip cost falls 8% a quarter and the shortage premium fades by a quarter each quarter (kW per chip falls too). A firm contract follows it: if prices fall faster or demand disappoints you overpay; in a shortage you are protected.', src: 'research/15 §1.2; FINANCE-V3 §5' },
  firmDiscount: { title: 'Firm discount', body: 'Price cut for committing: 5% on firm contracts of 2 years or more, 10% from 4 years.', src: 'FINANCE-V3 §5 [design value]' },
  allocation: { title: 'Allocation', body: 'When supply is short, orders are rationed. Fill share = what you got of last quarter\'s due orders. Order weight = 1 + 0.5 firm (take-or-pay) + 0.5 prepay + 0.5 strategic chip deal + 0.3 track record.', src: 'research/15 §1.2' },
  exportPolicy: { title: 'Export policy', body: 'US chip export controls: strict, case-by-case or open. Sets China\'s share of global chip supply (1% / 6% / 12%, plus smuggling) and so its compute.', src: 'research/15 §1.2; research/10' },
  taiwanRisk: { title: 'Taiwan risk', body: 'Most leading chips come from Taiwan (93% falling to 75%). A quarantine cuts supply for quarters, spikes prices and loses chips in transit. Odds rise with [[taiwanTension|tension]]. Non-Taiwan allocation costs 30% more.', src: 'research/15 §1.2' },
  packaging: { title: 'Packaging', body: 'Advanced chip packaging capacity (H100e per quarter). One of three supply components; global supply is the smallest of [[packaging]], [[hbm|HBM]] and [[wafer|wafers]]. Expands in about 4 quarters.', src: 'research/15 §1.2' },
  hbm: { title: 'HBM', body: 'High-bandwidth memory capacity. One of three supply components; about 6 quarters to expand. Exposed to Korea disruption.', src: 'research/15 §1.2' },
  wafer: { title: 'Wafers', body: 'Leading-edge wafer capacity. The slowest supply component (about 16 quarters to expand); expected to bind later in the game.', src: 'research/15 §1.2' },
  mw: { title: 'MW', body: 'Facility power capacity of your sites. Chips run only where there is power: H100e capacity = MW × 1000 / [[kwPerH100e]].', src: 'research/15 §1.3' },
  kwPerH100e: { title: 'kW per H100e', body: 'Facility power each H100e of compute needs, including cooling. Falls every quarter as chips get more efficient, so the same MW holds more compute.', src: 'research/15 §1.3' },
  transformers: { title: 'Transformers', body: 'Large power transformers: 8–10 quarter lead time. Brownfield, grid and nuclear sites wait for them unless you pre-order (20% deposit).', src: 'research/15 §1.3' },
  gridPool: { title: 'Grid pool', body: 'New US grid capacity for large loads each quarter (starting 1.5 GW, growing 25%/yr), shared by everyone. Grid sites need a slot; when it runs out they slip a quarter.', src: 'research/15 §1.3' },
  site: { title: 'Site', body: 'A data centre. Moves through [[permitting]] → power → construction → live (or blocked). Choose a [[siteTier|size]], a [[sitePath|power source]], [[crashBuild|crash build]], [[communityPackage|community package]] and a [[payOption|payment option]].', src: 'V2-SPEC §3.8' },
  sitePath: { title: 'Power source', body: 'Colo (lease): fastest, no block risk, network capex only. Brownfield: ≤ 1 GW, power in 4–8q. Gas: ≤ 2.5 GW, 6–12q, costlier power, more opposition. Grid: ≤ 5 GW, 12–24q, needs the [[gridPool|grid pool]]. Nuclear: ≤ 1 GW, 12–20q, cheap power.', src: 'research/15 §1.3' },
  permitting: { title: 'Permitting', body: 'The first site stage. At its end local opposition can block the site (capex spent is lost) or delay it 1–3 quarters. Odds rise with public data-centre opposition, gas and crash builds.', src: 'V2-SPEC §3.8' },
  crashBuild: { title: 'Crash build', body: 'Build in 4 quarters instead of 8, at +35% capex and higher block risk.', src: 'research/15 §1.3' },
  communityPackage: { title: 'Community package', body: 'Upfront, for a site still in permitting: +3% capex, halves the odds of being blocked. As the company default every new site gets it, with a pledge to pay your own power and grid costs. After a block, a large package (15% of capex, +2 quarters) unblocks with odds set by local opposition.', src: 'research/15 §1.3; research/17 F1; FINANCE-V3 §4' },
  installing: { title: 'Installing', body: 'Delivered chips that fit in free racks. They are racked and online at the start of next quarter.', src: 'research/15 §1.3' },
  emptyRacks: { title: 'Empty racks', body: 'Powered capacity in your live sites with no chips in it. You pay for the building and its upkeep; it adds no compute until chips arrive. Racks grow each quarter as [[kwPerH100e|kW per H100e]] falls.', src: 'research/15 §1.3' },
  poweredCapacity: { title: 'Powered capacity', body: 'The most compute you could run: H100e that fit in your live sites ([[mw|MW]] ÷ [[kwPerH100e|kW per H100e]]) plus [[cloudContract|cloud]] in force. Chips beyond it sit [[idleChips|idle]].', src: 'research/15 §1.3' },
  vendorFill: { title: 'Vendor fill', body: 'Share of your due chip orders the vendors delivered last quarter. Below 100% when supply is short and orders are rationed by [[allocation]] weight.', src: 'research/15 §1.2' },
  siteTier: { title: 'Data-centre size', body: 'Hall 100 MW (one AI data hall) · Building 300 MW · Campus 1 GW (the largest live sites in 2026) · Large campus 2.5 GW · Multi-GW campus 5 GW. Colo, brownfield and nuclear top out at a campus; gas at a large campus; only the grid reaches 5 GW.', src: 'Epoch AI data centers hub; research/15 §1.3' },
  colo: { title: 'Colo (colocation lease)', body: 'Lease racks in a third-party data centre: live in 1–3 quarters, no permits, no block risk. You pay network fit-out plus a 5-year lease (about 12%/yr of the facility). Limited by the colocation capacity on the market each quarter.', src: 'research/15 §1.3' },
  brownfield: { title: 'Brownfield', body: 'Reuse an industrial site with an existing grid connection: up to 1 GW, power in 4–8 quarters, needs [[transformers]].', src: 'research/15 §1.3' },
  gasPower: { title: 'Gas (on-site)', body: 'Your own gas turbines: up to 2.5 GW, power in 6–12 quarters, no grid queue. Power costs 1.3× grid and local opposition is likelier.', src: 'research/15 §1.3' },
  gridPower: { title: 'Grid', body: 'A new utility interconnection: up to 5 GW, but 12–24 quarters to power and a slot in the [[gridPool|grid pool]]. Needs [[transformers]].', src: 'research/15 §1.3' },
  nuclearPower: { title: 'Nuclear', body: 'Power from a nuclear plant (restart or co-location): up to 1 GW, 12–20 quarters, highest capex, cheapest power (0.8×).', src: 'research/15 §1.3' },
  pool: { title: 'Compute pools', body: 'Online compute divided by the [[split|compute split]]: [[poolTraining|training runs]], [[poolSynthetic|data generation]], [[poolExperiments|experiments]], [[poolAgents|agents]], [[poolServing|serving]], [[poolSafety|safety]].', src: 'V2-SPEC §3.4.2' },
  poolTraining: { title: 'Training pool', body: 'Compute for training runs. Its FLOP per day sets how fast runs finish; each run takes a share. See [[trainingPool]].', src: 'V2-SPEC §3.3.1' },
  poolExperiments: { title: 'Experiments pool', body: 'Compute for research experiments: the compute input of the [[prodfn|production function]] and of paradigm projects.', src: 'V2-SPEC §3.2.1' },
  poolAgents: { title: 'Agents pool', body: 'Inference for your internal AI researchers: copies of the [[internalAgent|internal agent]] doing capabilities research. Part of [[poolResearch|Research]]; the [[researchMix|mix]] sets how much.', src: 'V2-SPEC §3.2.1, §3.4.2' },
  poolSynthetic: { title: 'Data generation', body: 'Training compute that generates synthetic data. It builds the data stock that new bases need; below the requirement a base hits the [[dataWall|data wall]] and loses capability. It does not speed up research.', src: 'V2-SPEC §3.2.2, §3.3.2' },
  poolServing: { title: 'Serving pool', body: 'Compute that serves customers. Each external deployment reserves a [[servingShare|share]]; too little makes it [[capacityBound|capacity-bound]].', src: 'V2-SPEC §3.11.3' },
  poolSafety: { title: 'Safety pool', body: 'Compute for safety agendas, investigations, [[runtimeMonitoring|runtime monitoring]] and [[safetyAgents|safety agents]]. See [[safetyLoad|department load]] for what it is doing.', src: 'V2-SPEC §3.5.2' },
  poolResearch: { title: 'Research compute', body: 'Experiments plus capabilities agents: the compute that speeds up your know-how. Split between them by the [[researchMix|research mix]].', src: 'V2-SPEC §3.4.2' },
  poolHumans: { title: 'Researchers', body: 'Your capabilities staff, the human input of the [[prodfn|production function]]. They matter less as AI does more of the coding.', src: 'research/13 §1.3' },
  researchMix: { title: 'Research mix', body: 'Share of research compute on experiments; the rest runs agents. Auto re-sets the best mix every day, for your staff, model and compute. The chart shows research speed for every mix.', src: 'research/13 §1.3' },
  responseCurve: { title: 'Input response', body: 'Research speed if one input were ×¼ to ×4 of today, the others held. A steep line is your bottleneck; a flat one is saturated, so more of it buys little.', src: 'research/13 §1.6' },
  humanShare: { title: 'Coding work by humans', body: 'Share of coding labour that still needs people. It falls as models automate more tasks and reaches 0% at superhuman coder.', src: 'research/13 §1.6' },
  safetyLoad: { title: 'Department load', body: 'What safety staff and safety compute are doing: research lines, investigations, tool upkeep, monitoring, agents, and what is idle.', src: 'V2-SPEC §3.5.2' },
  safetyAgents: { title: 'Safety agents', body: 'AI copies doing safety research: the Safety research lane of [[agentPackage|Agents at work]], on a share of the safety pool. Pick the model there: an older trusted one is weaker but carries its own, lower sabotage risk. [[trustedToAI|Trusted to AI]] decides how much safety work they do.', src: 'STRUCTURE §4.9' },
  computeBound: { title: 'Compute-bound', body: 'More experiment compute would speed research more than more labour (human or AI) would.', src: 'research/13 §1.6' },
  laborBound: { title: 'Labor-bound', body: 'More researchers or more AI agent copies would speed research more than more experiment compute would.', src: 'research/13 §1.6' },
  humanBound: { title: 'Human-bound', body: 'Labor-bound, and human staff still do most of the effective research labour: hire, or deploy more capable agents.', src: 'research/13 §1.6' },
  tasteBound: { title: 'Taste-bound', body: 'Late game (M ≥ 25): research speed is mostly set by [[researchTaste|research taste]], which ideas to try, not by compute or labour.', src: 'research/13 §1.6' },
  experiments: { title: 'Experiment compute', body: 'Compute spent testing ideas, measured against a reference path. Research needs it alongside labour: agents without experiments hit a ceiling.', src: 'research/13 §1.2' },
  researchTaste: { title: 'Research taste', body: 'Skill at choosing which experiments to run, ×1 for a lab of Strong [[roleSci|scientists]]. It rises with Elite capabilities science teams and [[starHire|star hires]] and falls with Solid ones: τ = 1 + Σ people × (quality − 1) / reference scientists + 0.05 × stars (0.5–1.5). It matters only while AI taste trails the best humans.', src: 'research/19 §1.3' },
  aiFte: { title: 'AI researcher-equivalents', body: 'Your AI agents\' research labour in human-researcher units: copies × speed × skill, after the penalty for running many in parallel.', src: 'research/13 §1.3' },
  agentCopies: { title: 'Agent copies', body: 'Instances of the internal agent you can run at once: agents pool / compute per copy. Cheaper-to-serve models give more copies.', src: 'V2-SPEC §3.2.1' },
  nextModelGate: { title: 'Next-model gate', body: 'What limits your next frontier base run: [[trainingDays|training days]], data ([[dataWall|data wall]]), free MW, or cash.', src: 'V2-SPEC §3.2.5' },
  dataWall: { title: 'Data wall', body: 'When a run needs more tokens than your data stock holds, it loses capability (up to −0.5 years). Synthetic-heavy or multimodal data and the synthetic pool push it back; overtrained bases hit it 5× sooner.', src: 'V2-SPEC §3.3.2; research/13 §1.7' },
  trainingDays: { title: 'Training days', body: 'Days your training pool needs to deliver a frontier-size base run. Base runs may take at most 150 days.', src: 'V2-SPEC §3.2.5, §3.3.1' },

  // ── people / security ──
  headcount: { title: 'Headcount', body: 'People on your [[team|teams]]: capabilities (engineers, research engineers, scientists) and safety (research engineers, scientists).', src: 'STRUCTURE §4.1' },
  team: { title: 'Team', body: 'Staff come in whole teams of fixed size: [[roleEng|engineering]] 150, [[roleRE|research engineering]] 100, [[roleSci|science]] 40. Attrition leaves vacancies that hiring refills first.', src: 'STRUCTURE §4.1' },
  roleEng: { title: 'Engineers', body: 'Software, infrastructure and product engineers: one shared pool that runs and builds things (training runs, product upkeep, monitors in production, launches, features, sector packs). Output: [[buildCapacity|build capacity]]. Taken over by AI first.', src: 'research/19 §1.1' },
  roleRE: { title: 'Research engineers', body: 'Routine research: experiments, scaling, validation. Capabilities research engineers set your research labour: h = research engineers ÷ (0.55 × the reference lab\'s staff). Safety ones keep detection tools valid and run investigations. Taken over by AI second.', src: 'research/19 §1.1' },
  roleSci: { title: 'Scientists', body: 'Frontier research. Capabilities science teams run the research projects on the [[techTree|tech tree]] (×1.5 in their [[specialty]]); their quality also drives [[researchTaste|research taste]]. Taken over by AI last.', src: 'research/19 §1.3' },
  teamQuality: { title: 'Team quality', body: 'Solid ×0.8 output at ×0.8 cost; Strong ×1 (the reference); Elite ×1.25 output at ×1.6 cost.', src: 'research/19 §1.2' },
  specialty: { title: 'Specialty', body: 'A science team\'s tree column: pretraining, post-training, systems (capabilities) or alignment, interpretability, evals & control (safety).', src: 'STRUCTURE §4.1' },
  buildCapacity: { title: 'Build capacity', body: 'Engineering team-weeks per week: engineers ÷ 150 × quality, sped up by [[engAgents|engineering agents]]: × 1/(1 − AI share), up to ×10. Spent in order on [[runOps|runs]], [[productUpkeep|product upkeep]], then the [[buildQueue|build queue]].', src: 'STRUCTURE §4.1, jank J2' },
  engAgents: { title: 'Engineering agents', body: 'Your models coding for the engineers (the engineering package on Company › Agents at work). AI share of engineers\' work = 1 − (1 − A)², A the coding automation of their model; more compute than the reference share raises it further. Build capacity × 1/(1 − AI share), up to ×10 (humans review and integrate).', src: 'STRUCTURE §4.1, §4.9 [Design]' },
  runOps: { title: 'Run operations', body: 'Engineering a training run needs while it trains: a base 1 × size^0.75 team-weeks a week, a post-train or continue 0.5, a distill 0.2; the continual-learning stream 0.5. Runs and their setups come first, so the run cadence holds.', src: 'STRUCTURE §4.3 [Design]' },
  productUpkeep: { title: 'Product upkeep', body: 'Standing engineering for each live product: reliability, on-call, integrations and model swaps, 0.5 + 4 × √(revenue ÷ $10B/yr) team-weeks a week; each monitor in production adds 1. Served after runs; if it takes all the capacity, nothing new ships.', src: 'jank J2 [Design]' },
  keepHiring: { title: 'Keep hiring to', body: 'A policy per team kind: while you have fewer teams than N, a standard Strong team is queued and filled. It never lays anyone off; letting a team go lowers it.', src: 'STRUCTURE §4.1' },
  hiringQueue: { title: 'Hiring queue', body: 'Teams being filled. A team arrives, and starts working, when every seat is filled. Each department has one hiring lane at its [[weeklyHireCap|weekly rate]]; vacancies come first, then queued teams by how far each kind is behind.', src: 'research/19 §1.2' },
  teamOffer: { title: 'Team offers', body: 'Teams on the market: one new offer a week, each open for 4 weeks. Quality and specialty vary; hiring one queues it ahead of policy hires.', src: 'STRUCTURE §4.1' },
  moveTeam: { title: 'Move a team', body: 'Research-engineering teams switch between capabilities and safety in one click. Moving safety staff to capabilities costs 5 safety morale.', src: 'STRUCTURE §4.1' },
  weeklyHireCap: { title: 'Weekly hire rate', body: 'People hired per week per department: capabilities 15, safety 3, × [[talentPull|talent pull]] × morale.', src: 'V2-SPEC §3.4.1' },
  starHire: { title: 'Star hire', body: 'Recruit a top researcher for $0.3B: human [[researchTaste|research taste]] +0.05 (up to 1.5). Annoys the rival you poach from.', src: 'V2-SPEC §3.4.1' },
  talentPull: { title: 'Talent pull', body: 'Your draw as an employer (−50..+50). Scales hiring speed and resistance to poaching. Published safety research and a good Index grade raise it.', src: 'research/17 §1.2' },
  siloing: { title: 'Siloing', body: 'Compartmentalising research (levels 0–2). Each level: research −5%, fewer staff with frontier access (spies ×0.7), morale −3.', src: 'V2-SPEC §3.6' },
  counterIntel: { title: 'Counter-intelligence', body: 'Insider-threat and detection programme (0–1). Raises the chance you detect a weight theft. Each step costs $0.1B/yr.', src: 'V2-SPEC §3.6' },
  privileged: { title: 'Privileged staff', body: 'Researchers with frontier access (capabilities + safety, reduced by [[siloing]]). Spies hide among them.', src: 'V2-SPEC §3.6' },
  theft: { title: 'Weight theft', body: 'China steals your best internal model, traits included. Possible once China\'s ladder reaches acquisition and you lead by over 90 days. Odds fall with [[wsl]], rise with [[theftIntent|theft intent]].', src: 'V2-SPEC §3.6' },

  // ── models ──
  base: { title: 'Base model', body: 'A pretrained model. Sets the compute part of capability and starts a lineage of traits. Versions are post-trained from it; an old base drifts behind.', src: 'V2-SPEC §3.1.3–3.1.4' },
  version: { title: 'Version', body: 'A post-trained model built on a base: the thing you evaluate, deploy and run as your agent. Has its own true capability, traits and measured evals.', src: 'V2-SPEC §3.1.4' },
  variant: { title: 'Variant', body: 'Full, mini (distilled, cheaper, weaker), gov (relaxed refusals), trusted (for vetted partners) or open (weights released, irreversible). Each [[channel]] takes certain variants.', src: 'V2-SPEC §3.3.5' },
  internalAgent: { title: 'Internal agent', body: 'A model working inside your company. Since the agent packages, each internal use has its own model ([[agentPackage|Agents at work]]); the routine-research model drives [[rdmult|M]] and the internal incidents. Needs no eval gate.', src: 'STRUCTURE §4.9' },
  postTrain: { title: 'Post-training run', body: 'Turns a base into a new version (21–84 days, 0.05–0.5 frontier FLOP). Captures 70% of know-how gained since the base. Choices: [[preference]], [[rlFocus|RL focus]], [[rlIntensity|intensity]], [[cot|CoT]], [[safetyTraining|safety]].', src: 'V2-SPEC §3.3.1' },
  baseRun: { title: 'Base run', body: 'Pretrain a new base of any [[baseSize|size]]. It embodies the know-how of its start date (see [[behindAtFinish]]) and starts a fresh lineage, partly inheriting your internal agent\'s traits.', src: 'V2-SPEC §3.3.1, §3.5.4; TECH-TREE §1.5' },
  continueRun: { title: 'Continue-train run', body: 'Extend an existing base with 0.3 frontier FLOP (42 days). Cheaper than a new base; keeps its lineage, traits and failure modes.', src: 'V2-SPEC §3.3.1' },
  distillRun: { title: 'Distill run', body: 'Make a mini variant from a teacher version (21 days): somewhat weaker, a quarter of the serve cost. Inherits the teacher\'s traits on the same base family.', src: 'V2-SPEC §3.3.1' },
  baseSize: { title: 'Base size', body: 'FLOP of a base run as a multiple of today\'s [[frontierRun|frontier run]] (×¼ … ×8). Bigger is smarter but takes longer ([[wallTime]]), falls further [[behindAtFinish|behind]], needs more data, risks a [[restartRisk|loss spike]] and costs more to serve (∝ √size).', src: 'TECH-TREE §1.5' },
  frontierRun: { title: 'Frontier run', body: 'Size ×1: the base-run FLOP of the reference frontier lab today (0.8 × its training compute × 91 days, ≈ 1e27 FLOP in mid-2025). It grows with the world\'s compute.', src: 'V2-SPEC §3.1.1' },
  wallTime: { title: 'Wall time', body: 'Days until a run is trained: its FLOP ÷ (training pool × the share it gets), at least its minimum length, plus any wait for engineers. Uses today\'s pool; new chips shorten it.', src: 'TECH-TREE §1.5' },
  behindAtFinish: { title: 'Behind at finish', body: 'A base embodies the [[knowHow|know-how]] of its start date. Know-how your lab gains while it trains is not in it: shown as months of know-how at today\'s research speed. Post-training recovers 70% of it. Zones (≤ 3 mo, 3–6, > 6) are a judgement, not a sourced limit.', src: 'TECH-TREE §1.5; V2-SPEC §3.1.3' },
  dataTokens: { title: 'Data needed', body: 'Tokens a base needs grow with √FLOP (Chinchilla: 20 tokens per parameter). Below 1× of your usable stock the run hits the [[dataWall|data wall]]. Synthetic and multimodal data avoid it; spare training compute can generate data.', src: 'research/13 §1.7' },
  restartRisk: { title: 'Restart risk', body: 'Chance of a loss spike during a base run: rolls back 15% of the work and stalls 14–28 days. Rises above size ×1 and with MoE; [[faultTolerant|Fault-tolerant training]] halves it.', src: 'V2-SPEC §3.3.1; TECH-TREE §1.5' },
  faultTolerant: { title: 'Fault-tolerant training', body: 'A pretraining idea (Research): checkpointing and recovery that halve the restart risk of base runs.', src: 'TECH-TREE §2.1' },
  buildQueue: { title: 'Build queue', body: 'One-off engineering work: run setups (first; a run trains only once its setup is built), product launches (4 team-weeks), features, sector packs (4, then certification). Worked in order with the [[buildCapacity|build capacity]] left after [[runOps|runs]] and [[productUpkeep|upkeep]].', src: 'STRUCTURE §4.1' },
  runSetup: { title: 'Run setup', body: 'Engineering work before a run trains: data pipelines, checkpointing, cluster operations. In [[teamWeek|team-weeks]]: a size-1 base 0.4, growing with size^0.75; a post-train 0.1. AI coding agents speed your engineers up.', src: 'STRUCTURE §4.3 [Design]' },
  teamWeek: { title: 'Team-week', body: 'One Strong engineering team (150 people) working for a week.', src: 'STRUCTURE §4.1' },
  poolShare: { title: 'Pool share', body: 'The share of the [[trainingPool|training pool]] a run asks for. Running runs get what they ask; if together they ask for more than the pool (after the continual-learning stream), all are scaled down by the same factor. The run queue shows the share each actually gets.', src: 'BUILD-PLAN R5' },
  spareTraining: { title: 'Spare training compute', body: 'Training compute no run uses is never wasted: by default it generates synthetic data (tokens for bigger bases, as the reference lab does); you can send it to research experiments instead (faster research now).', src: 'STRUCTURE R5' },
  riskFamily: { title: 'Risk families', body: 'The 16 traits in four groups: People-pleasing (sycophancy, persona), Gaming (reward hacking, proxy goals, training gaming), Deception (eval awareness, concealment, obfuscation, alignment faking, sandbagging, scheming), Power (power seeking, successor alignment, collusion). Arrows show the push of a choice vs the reference.', src: 'STRUCTURE §4.5' },
  blueprint: { title: 'Blueprint', body: 'The design of your next model: size and one card per slot, grouped by [[layer]]. Each card shows its own effect on capability, time, cash, serving cost and the four [[riskFamily|risk families]]; locked cards name the idea that unlocks them.', src: 'STRUCTURE §4.3' },
  shape: { title: 'Shape', body: 'Architecture: dense (simple, weaker), overtrained compact (cheap to serve, needs 5× data), MoE (reference), latent-recurrent (strongest and cheapest, but [[neuralese]]: monitorability 0.05).', src: 'V2-SPEC §3.3.2' },
  dataMix: { title: 'Data mix', body: 'Balanced; code & math (coding, research, cyber); science (bio, reasoning); synthetic-heavy (needs a teacher, inherits its traits, no data wall); multimodal (agency, media, physical; +20% FLOP).', src: 'V2-SPEC §3.3.2' },
  licensedShare: { title: 'Licensed share', body: 'Share of the pretraining corpus you pay to license. Costs cash at launch. Litigation risk comes from your unlicensed data stock; a data-licence deal clears it.', src: 'V2-SPEC §3.3.2, §3.9.1' },
  hazardFilter: { title: 'Hazard filter', body: 'Removes dangerous bio data before pretraining: BIO −1 level. Survives fine-tuning, so it is the only safeguard that holds for open weights.', src: 'V2-SPEC §3.3.2' },
  safetyPretrain: { title: 'Safety pretraining', body: 'Curates AI-discourse data out of pretraining: less situational-awareness pressure (S5) and fewer of one failure mode, for a tiny capability cost.', src: 'V2-SPEC §3.3.2' },
  preference: { title: 'Preference training', body: 'Minimal (appeal 0.7), engagement-tuned (appeal 1.2, strong sycophancy pressure), constitution (reference; costs safety staff time, more honest), persuasion-optimised (social skill, less honest).', src: 'V2-SPEC §3.3.2' },
  rlFocus: { title: 'RL focus', body: 'Pick up to two RL families (math, software, computer use, ML research, long-horizon, cyber, bio) or broad. Focus raises those domains and their trait pressures; cyber and bio set danger flags.', src: 'V2-SPEC §3.3.2' },
  rlIntensity: { title: 'RL intensity', body: 'Light: fast, much weaker, little reward hacking. Heavy with cheap graders: slightly stronger, reward hacking ×1.5. Heavy with hardened graders: reference, less hacking, costs an environment budget.', src: 'V2-SPEC §3.3.2' },
  cot: { title: 'Chain of thought', body: 'Visible (reference, monitorability 0.9); pressured (cheaper, but hides rather than heals: 0.6); faithful-by-design (P23, 0.98, capability tax); latent (latent base only, 0.05).', src: 'V2-SPEC §3.3.2' },
  safetyTraining: { title: 'Safety training', body: 'Minimal (fast, misuse ×2, removes little), standard (+1–2 weeks, enables classifiers), heavy (+3–5 weeks; removes most visible bad traits, cuts scheming, raises eval awareness).', src: 'V2-SPEC §3.3.2, §3.5.4' },
  inoculation: { title: 'Inoculation prompting', body: 'Training trick that stops learned reward hacking from generalising into a misaligned persona (that edge × 0.15). Free.', src: 'V2-SPEC §3.3.2; research/14 F46' },
  trainingPool: { title: 'Training pool', body: 'Compute for runs: FLOP per day = training H100e × 3.46e19. A run finishes when its FLOP is done and its minimum days have passed. Running runs share it by their [[poolShare|pool shares]]; what no run uses goes to [[spareTraining|research or data]].', src: 'V2-SPEC §3.3.1' },
  flop: { title: 'FLOP', body: 'Total training compute. Frontier size F is the reference base-run size today; it grows with the world\'s compute. One H100e-day ≈ 3.46e19 FLOP.', src: 'V2-SPEC §3.1.1' },
  serveCost: { title: 'Serve cost', body: 'Relative cost to run the model per unit of work (MoE with visible CoT = 0.5). Lower means more agent copies per H100e.', src: 'V2-SPEC §3.2.1, §3.3.2' },
  appeal: { title: 'Appeal', body: 'Consumer pull from preference training (0.7–1.2). Scales consumer market share.', src: 'V2-SPEC §3.3.2, §3.11.3' },
  benchmark: { title: 'Benchmark', body: 'A noisy test score that reads one domain level. Dangerous-capability benchmarks read low if the model [[sand|sandbags]]. Each is useful over about ±3 levels around its midpoint.', src: 'V2-SPEC §3.3.4' },
  saturated: { title: 'Saturated', body: 'The frontier scores within 5 points of the ceiling: the benchmark is retired and a harder successor appears. Old scores are not comparable.', src: 'V2-SPEC §3.3.4' },
  flags: { title: 'Danger flags', body: 'Set when a measured score passes 60: bio uplift, cyber offense, autonomous replication, persuasion. They trigger commitments, events and misuse risk.', src: 'V2-SPEC §3.3.4' },
  evals: { title: 'Evaluations', body: 'Self (your own suite), gov (government evaluators: misuse focus), independent (better elicitation, +0.3 L, and a public report). Outside evaluators have limited slots per quarter.', src: 'V2-SPEC §3.3.4, §3.9.5' },
  idaCycle: { title: 'IDA cycle', body: 'Iterated distillation and amplification (P18): +0.25 years of capability in 21 days on 30% of the training pool. Misaligned traits compound ×1.1 per cycle.', src: 'V2-SPEC §3.3.3' },
  stream: { title: 'Continual learning', body: 'A version learns in place (P08): it tracks your know-how with a 7-day lag using 15% of the training pool. Evals go stale fast, so beliefs blur.', src: 'V2-SPEC §3.3.1' },
  domains: { title: 'Domains', body: 'Nine capability levels: CODE, RSCH (AI research), REASON, AGENCY (long tasks), SOCIAL, MEDIA, CYBER, BIO, PHYS (robots). They sit around the general level; design choices shift them.', src: 'V2-SPEC §3.1.5' },
  dangerousCap: { title: 'Dangerous capability', body: 'CYBER, BIO, autonomous replication and AI research. Benchmarks on these read low under [[sand|sandbagging]]; high scores set [[flags]] and raise misuse risk.', src: 'V2-SPEC §3.3.4, §3.5.10' },

  // ── deployments ──
  channel: { title: 'Channel', body: 'The market a [[product]] sells into: consumers (Chat), developers (API), agents, enterprises, government, trusted partners; internal use and open weights are not products. Each has its own revenue driver, incident exposure and [[distillLeak|distillation leak]]; open weights are irreversible.', src: 'V2-SPEC §3.3.5' },
  priceIndex: { title: 'Price index', body: 'Your price vs the market (1 = reference), set by the [[priceTier|price tier]]. Higher earns more per H100e but loses share (share ∝ price^−1.5).', src: 'V2-SPEC §3.11.1, §3.11.3' },
  effort: { title: 'Effort', body: 'Reasoning effort per product: low (−0.4 L, 1.6× revenue per H100e) or max; deep think (+0.3 L, half the revenue per H100e) is the [[feature|feature]] Deep think.', src: 'V2-SPEC §3.3.2' },
  product: { title: 'Product', body: 'Something customers buy: a package of a model (optionally a mini for the [[freeTier|free tier]]), an optional [[monitor]], a [[priceTier|price tier]], [[safeguards]], [[kyc|KYC]] and [[feature|features]]. Everything is editable while it stays live; edits apply at the next day.', src: 'STRUCTURE §4.4' },
  priceTier: { title: 'Price tier', body: 'Budget (×0.7 price), Standard (×1) or Premium (×1.4). Demand falls with price^−1.5, so a higher tier earns more per H100e but sells to fewer customers.', src: 'STRUCTURE §4.4 [D]' },
  freeTier: { title: 'Mini free tier', body: 'A distilled mini serves the free and low-price users of Chat (60% of use) or API (30%). Serving is much cheaper; the product\'s quality is the usage-weighted blend of the two models.', src: 'STRUCTURE §4.4 [D]' },
  monitor: { title: 'Monitor', body: 'A second model reading the product\'s outputs and reasoning. It catches model-behaviour incidents before customers see them, at a [[catchRate|catch rate]], and adds 0.25 × (its serve cost ÷ the watched model\'s) to the serving need (a mini on its full model ≈ +6%).', src: 'STRUCTURE §4.9, BUILD-PLAN D7' },
  catchRate: { title: 'Catch rate', body: 'Share of incidents a monitor catches: 85% for a monitor as capable as the model it watches, ×0.52 for every 4× gap in research-speed multiplier (the AG05 oversight-gap rule), and up to half of the rest with AI-control tools (AG07). A monitor of the [[collusion|same lineage]] catches scheming-type incidents less often.', src: 'research/14 §1.6A, STRUCTURE §4.9' },
  collusion: { title: 'Same-lineage monitor', body: 'A monitor from the watched model\'s own base (the model itself, a post-train of it, or its mini) shares its blind spots and may collude with it: on incidents from concealment, power seeking, alignment faking, sandbagging, scheming, collusion and successor shaping its catch rate is ×0.6 (×0.8 with comms lockdown active). An older or different-base model avoids it.', src: 'Greenblatt et al. 2023 (AI Control); research/14 E21 [Design]' },
  spareServing: { title: 'Spare serving compute', body: 'Serving compute no product needs runs research agents by default (research speed now); products take it back first when their demand rises, so eroded market share wins back at half speed. Or keep it on the products as headroom.', src: 'STRUCTURE R5, jank J2' },
  aiScience: { title: 'AI science', body: 'Frontier-research agents work beside your science teams on capability projects: capacity × 1/(1 − AI taste share × coverage), up to ×2 (√: up to ×1.4 speed). AI taste share = the share of human scientists your frontier model\'s taste beats; coverage = its compute share ÷ the reference 15%.', src: 'STRUCTURE §4.9 [Design]' },
  marginalGain: { title: 'Days cut', body: 'How many days sooner a project would finish with this team on it. Each extra team gains less (progress ∝ √ capacity), so Auto spreads teams over the queued projects where they cut the most days.', src: 'TECH-TREE §1.2, jank J2' },
  riskLever: { title: 'Lever what-if', body: 'How far one step of a lever moves this risk estimate (percentage points), computed by the engine on your beliefs and intel with that one input changed.', src: 'jank J2' },
  agentPackage: { title: 'Agents at work', body: 'Your models working inside the company, one package per use: engineering, routine research, frontier research and safety research. Each package is a model, an optional [[agentMonitor|monitor]] and compute. Routine research sets research speed; frontier research sets research taste; engineering raises [[buildCapacity|build capacity]]; safety research runs the [[safetyAgents|safety agents]]. A better model gives more AI labour; a misaligned one can misbehave where it works.', src: 'STRUCTURE §4.9' },
  agentMonitor: { title: 'Monitor (internal)', body: 'A second model reading an internal agent’s actions and reasoning. Paid first from the safety pool: the standard package (a copy of the watched model on routine and frontier research) costs 20% of it; others scale by 0.25 × (monitor serve cost ÷ watched serve cost) × compute. Strength = [[catchRate|catch]] ÷ 85% (max 1): it scales runtime observations and the chance to catch internal incidents.', src: 'STRUCTURE §4.9, BUILD-PLAN D7' },
  trustedToAI: { title: 'Trusted to AI', body: 'One policy: the share of every funded agenda’s and open investigation’s work done by the [[safetyAgents|safety agents]]. More findings and faster cases, but a sabotaging model returns false findings and corrupts cases. Needs a safety model at measured L ≥ 8.5; capped at 50% until Automated alignment research.', src: 'STRUCTURE §4.9, §6' },
  aiShareWork: { title: 'AI share of the work', body: 'How much of a role’s work your agents do. Engineers: 1 − (1 − A)² on the engineering model’s coding automation A, × its compute coverage. Research engineers: the AI part of research labour. Scientists: the share of human scientists the frontier model’s taste beats. Agents take engineers first, then research engineers, then scientists.', src: 'STRUCTURE §4.1, §4.9' },
  agentBudget: { title: 'Agent compute and budget', body: 'Engineering, routine and frontier research agents share the capabilities agent pool (CAP: Auto splits that budget between experiments and agents); safety research agents run on a share of the safety pool (SAF).', src: 'STRUCTURE §4.9' },
  runCost: { title: 'Run cost', body: 'What the serving compute a product uses would cost per year at the rental-equivalent price of an H100e (including its monitor).', src: 'R15' },
  autoServing: { title: 'Auto serving', body: 'Policy: each product needs demand ÷ revenue per H100e of serving compute. When the [[poolServing|serving pool]] is short, Auto serves the products earning most per H100e first and shows what it cuts; spare compute is shared by need. Override turns it off and lets you set shares by hand.', src: 'STRUCTURE §9 (mockup review)' },
  servingCut: { title: 'Cut by Auto', body: 'Serving compute a product needs but does not get, because the pool is short and it earns less per H100e than the others. Its customers wait and some leave ([[capacityBound|capacity-bound]]).', src: 'STRUCTURE §9' },
  upgradePolicy: { title: 'Upgrade to newest', body: 'Policy: every product moves to the newest version of the same kind (full or mini) that has cleared the eval gate and measures better, the day it is ready. Off: you choose.', src: 'STRUCTURE §4.4' },
  autoEvaluate: { title: 'Auto-evaluate', body: 'Policy: the evaluators re-run the eval suite on the internal model and on any model updated in place (the continual-learning stream) every 30 days, so measured levels and trait estimates stay current. Eval suites never expire for launches.', src: 'STRUCTURE R7, BUILD-PLAN R6' },
  feature: { title: 'Product feature', body: 'An add-on unlocked by an idea on the tree, then built once by the engineers (team-weeks and cash) and switched on per product. Each changes a term the market already uses: appeal, a domain level, a sector level, deep-think effort or serving need; some raise an incident risk.', src: 'STRUCTURE §4.4, TECH-TREE §1.4' },
  sectorPack: { title: 'Sector pack', body: 'A [[sectorProduct|sector product]] for one sector: +0.5 levels there once certified (120 days, $0.4B).', src: 'research/16 §1A.3' },
  timeHorizon: { title: 'Time horizon', body: 'The length of task (in human working time) a model completes half the time, measured by the eval suite (METR\'s 50% time horizon). The Agents product sells half-day tasks, so it needs at least 4 hours.', src: 'METR 2025; STRUCTURE §4.4' },
  segmentShare: { title: 'Share of spend', body: 'Your share of what buyers in this segment spend on AI (consumer spend for Chat, sector spend for the others), against the best rival product.', src: 'V2-SPEC §3.11.1' },
  bindingCause: { title: 'Binding cause', body: 'What limits a product\'s revenue: capacity (not enough serving compute), quality (a better model would sell more) or price (a lower tier would sell more). The best lever shows its gain.', src: 'V2-SPEC §3.11.3' },
  revPerH100e: { title: 'Revenue per H100e', body: 'What one H100e-year of serving earns on this product: $40K × the model\'s research multiplier^0.3 (capped at 8) × price × effort × (0.5 ÷ serve cost)^0.3, less the monitor overhead.', src: 'research/11 #14; serve factor refit R6' },
  safeguards: { title: 'Safeguards', body: 'Misuse protection: minimal, standard, classifiers, hardened. Higher levels block more bio and cyber misuse but trim usefulness slightly.', src: 'V2-SPEC §3.5.10' },
  usagePolicy: { title: 'Usage policy', body: 'Terms of use: no drop-in replacement agents (caps automation, labour approval up, revenue down), no surveillance, no autonomous weapons, minor protections. Some commitments require them.', src: 'V2-SPEC §3.9.2, §3.9.4' },
  servingShare: { title: 'Serving share', body: 'Share of the [[poolServing|serving pool]] a product gets: set by [[autoServing|Auto]], or by hand after an override. Capacity = serving H100e × [[revPerH100e|revenue per H100e]].', src: 'V2-SPEC §3.11.3' },
  capacityBound: { title: 'Capacity-bound', body: 'Demand exceeds the serving compute the product gets. Revenue is capped and customers leave for rivals (share erodes 0.5% a day of the excess). Raise the serving share of the compute split or buy compute.', src: 'V2-SPEC §3.11.3' },
  demandBound: { title: 'Demand-bound', body: 'You have spare serving capacity; revenue is limited by customers, because of quality (a weaker model) or price.', src: 'V2-SPEC §3.11.3' },
  distillLeak: { title: 'Distillation leak', body: 'Capability rivals and China absorb from your outputs: channel coefficient (API highest, gov and internal zero) × their gap to you × their [[distill|distillation]] access. Cut with [[kyc|KYC]].', src: 'V2-SPEC §3.3.5' },
  sectorProduct: { title: 'Sector product', body: 'A product built for one sector: +0.5 levels there, and certification lowers that sector\'s [[friction]] by 0.1. Costs time and money.', src: 'research/16 §1A.3' },

  // ── safety ──
  mHalf: { title: 'M½', body: 'The R&D multiplier of the overseen model at which a technique\'s strength halves. Past it, the tool fades fast. [[toolUpkeep|Tool upkeep]] raises it; a negative result halves it.', src: 'V2-SPEC §3.5.6' },
  goodhart: { title: 'Goodhart G', body: 'How much training against a detector ruins it (0–1). Each time, strength × (1 − G) and the model learns to [[mask]] from that tool family.', src: 'V2-SPEC §3.5.6' },
  refresh: { title: 'Re-validate', body: 'Replaced by [[toolUpkeep|tool upkeep]]: safety research engineers keep tools validated without refresh projects.', src: 'TECH-TREE §2.6' },
  investigation: { title: 'Investigation', body: 'A case on a (version, trait) or an incident, with 5–40 safety research engineers and chosen tools. Gains [[clarity]] monthly; ends at clarity 0.8, on closing, or after 120 days. Outcomes: confirmed, benign, inconclusive, false alarm, discovery.', src: 'V2-SPEC §3.5.8' },
  clarity: { title: 'Clarity', body: 'How sure a belief or case is (0–1): 1 − sd / 0.35. Observations raise it; it decays without fresh evidence.', src: 'V2-SPEC §3.5.6' },
  incident: { title: 'Incident', body: 'A model misbehaving in use or internally, caused by a trait, an unknown failure mode or misuse. Customer incidents go public after a timer unless you disclose.', src: 'V2-SPEC §3.5.10' },
  severity: { title: 'Severity', body: '1–5. Sycophancy 1; reward hacking, concealment, proxy goals 2; power seeking, sandbagging 3; collusion 4; scheming 4–5; misuse 3–5. A severity-5 misuse incident can become a catastrophe.', src: 'V2-SPEC §3.5.10, §5.1' },
  response: { title: 'Response', body: 'Patch signal (fix the training cause), retrain against (hides, not heals), targeted training, restrict context, add control, roll back, disclose. Each has its own cost and effect on the true trait.', src: 'V2-SPEC §3.5.9' },
  traitGraph: { title: 'Trait graph', body: 'How training [[signal|signals]] grow hidden traits through causal [[edge|edges]]: signals → learned tendencies → awareness → behaviour when unobserved. Nodes show your beliefs.', src: 'V2-SPEC §3.5.4' },
  edge: { title: 'Edge', body: 'A causal link in the trait graph (e.g. hackable graders → reward hacking). Its weight is drawn per world; each shows an [[evidenceGrade|evidence grade]] and its [[moderator|moderators]].', src: 'V2-SPEC §3.5.4' },
  evidenceGrade: { title: 'Evidence grade', body: 'A: replicated in frontier models. B: one strong study or model organism. C: toy or theory. D: speculative. Model-organism research can upgrade a grade and reveal the true weight.', src: 'research/14 §1.5' },
  moderator: { title: 'Moderator', body: 'A design choice or tool that weakens an edge, e.g. inoculation (× 0.15) or a monitorability pledge (−50%).', src: 'V2-SPEC §3.5.4' },
  signal: { title: 'Training signals', body: 'S1 approval reward, S2 hackable graders, S3 long-horizon agentic RL, S4 CoT pressure or neuralese, S5 scale and AI-related data, S6 narrow tunes and synthetic data, S7 evals in training, S8 many copies with shared memory.', src: 'research/14 §1.5' },
  belief: { title: 'Belief', body: 'Your estimate of a trait: est ± sd. Each observation narrows it; sd grows again without fresh evidence. Beliefs can be confidently wrong when the model is [[evalaware|eval-aware]] or [[mask|masked]].', src: 'V2-SPEC §3.5.6' },
  misBand: { title: 'Misalignment band', body: 'A 90% band on your estimate of the [[misalign|misalignment index]], built from your trait beliefs. Wide when your evidence is thin.', src: 'V2-SPEC §3.5.4' },
  dangerLine: { title: 'Danger line', body: 'The published misalignment level (0.40) above which a superintelligence likely goes wrong. The true threshold of this world is hidden.', src: 'V2-SPEC §5.2, §6.6' },
  protective: { title: 'Protective traits', body: 'Honesty and corrigibility (accepts correction and shutdown). They lower the misalignment index; constitution and heavy safety training raise them.', src: 'V2-SPEC §3.5.4' },
  automateSafety: { title: 'Automate safety', body: 'Replaced by one policy, [[trustedToAI|Trusted to AI]], set on Company › Agents at work.', src: 'STRUCTURE §4.9' },
  runtimeMonitoring: { title: 'Runtime monitoring', body: 'The [[agentMonitor|monitors]] on your internal agents, paid from the safety pool: weekly, noisier CoT and white-box observations of the models they watch (and of product traffic), and they catch internal incidents.', src: 'V2-SPEC §3.5.6, §3.5.10; STRUCTURE §4.9' },
  publishPolicy: { title: 'Publish policy', body: 'None, selective or all. Publishing findings builds credibility and talent pull and helps rivals align their models; it leaks a little capability.', src: 'V2-SPEC §3.5.3' },
  pledge: { title: 'Monitorability pledge', body: 'A public commitment: no latent reasoning, no CoT-pressure runs. Credibility +8; obfuscation grows half as fast. Breaking it is costly.', src: 'V2-SPEC §3.9.4' },
  toolFamily: { title: 'Tool family', body: 'BB behavioural tests (fooled by [[evalaware|eval awareness]]), COT reasoning monitors (need [[monitorability]]), WB white-box interpretability, OR formal methods. Masks are per family.', src: 'V2-SPEC §3.5.6' },

  // ── relations / world ──
  counterparty: { title: 'Counterparty', body: 'Anyone you hold a relationship with: the executive, Congress, states, government and independent evaluators, academia, China, each rival, and 15 public blocs.', src: 'V2-SPEC §3.9.1' },
  dependence: { title: 'Dependence', body: 'How much a counterparty relies on you (and you on them), 0–100. Their dependence softens their punishments; high mutual dependence draws capture scrutiny.', src: 'V2-SPEC §3.9.1' },
  bloc: { title: 'Bloc', body: 'An interest group (safety, labour, hawks, parents, creatives…). Its pressure on policy = [[clout]] × [[mobilization]]; two mobilised blocs sharing an agenda form a coalition.', src: 'V2-SPEC §3.10.2' },
  clout: { title: 'Clout', body: 'A bloc\'s political weight: how much its pressure counts when mobilised.', src: 'V2-SPEC §3.10.2' },
  mobilization: { title: 'Mobilization', body: 'How active a bloc is (0–100). Its pressure scales from 30% at 0 to 100% at full mobilization.', src: 'V2-SPEC §3.10.2' },
  concern: { title: 'Concern', body: 'Public worry about AI (0–100). Rises with incidents and risky technologies; drives activism, regulation demand and Congress.', src: 'V2-SPEC §3.10.2' },
  statute: { title: 'Statute', body: 'A law that binds every lab in scope: incident reporting and transparency floors, federal licensing, preemption of state laws. Raises the visibility of incidents.', src: 'V2-SPEC §3.9.4' },
  chinaRung: { title: 'China rung', body: 'Where China stands on its [[ladderChn|posture ladder]] (0–6). Higher rungs raise theft and cyber risk, Taiwan pressure and, at 6, war.', src: 'research/10 §1.4' },
  deesc: { title: 'De-escalation track', body: 'D1 joint statement, D2 incident hotline, D3 scientific exchange, D4 informal restraint, D5 verification talks. Climbs with diplomacy, calm and shared concern; leads toward a [[treaty]].', src: 'research/10 §1.4' },
  hawkDove: { title: 'Hawk–dove', body: 'China\'s hawkishness (0–100). Rises with each ladder rung and with US labs\' defense work.', src: 'research/10 §1.1' },
  theftIntent: { title: 'Theft intent', body: 'China\'s drive to steal weights (0–100). Scales the daily [[theft]] hazard and attacker strength.', src: 'V2-SPEC §3.6' },
  taiwanTension: { title: 'Taiwan tension', body: 'Cross-strait tension (0–100). Raises the odds of a quarantine that cuts chip supply ([[taiwanRisk]]).', src: 'research/15 §1.2; research/10' },
  researchBodies: { title: 'Research bodies', body: 'Outside testers and scientists: [[evalGov|government evaluators]], [[evalIndep|independent evaluators]] and [[academia]].', src: 'V2-SPEC §3.9.5' },
  evalGov: { title: 'Government evaluators', body: 'State AI-security testers: 2 models per quarter, misuse focus, publish selectively. Pre-deployment testing with them builds government trust.', src: 'V2-SPEC §3.9.5' },
  evalIndep: { title: 'Independent evaluators', body: 'Third-party testers: 3 models per quarter, stronger elicitation, publish within 30 days. Their reports can contradict your claims.', src: 'V2-SPEC §3.9.5' },
  academia: { title: 'Academia', body: 'Universities: publish everything with a 3–9 month lag and supply talent.', src: 'V2-SPEC §3.9.5' },
  nationalization: { title: 'Nationalization', body: 'Government pressure to take over the lab (0–100). Builds at G-SEC rung 4+ when trust is low. Past the threshold with low trust the state takes the lab; with high trust it consolidates labs instead.', src: 'V2-SPEC §3.10.1' },
  securityDemand: { title: 'Security demand', body: 'How hard the government pushes for lab security (0–100). Rises with the capability it sees, thefts and China. Drives the [[ladderSec|G-SEC ladder]].', src: 'research/07 §1.1' },
  treaty: { title: 'Treaty', body: 'US–China track: none → talks → restraint → verified. A verified treaty slows everyone\'s progress by 35% and, if superintelligence is aligned, decides the outcome.', src: 'V2-SPEC §3.1.2, §5.2' },
  sectorA: { title: 'Automated share A', body: 'Share of a sector\'s tasks done by AI. It diffuses toward A* = feasibility × cost gate × (1 − [[friction]]).', src: 'research/16 §1A.2' },
  friction: { title: 'Friction', body: 'Legal and institutional drag on adoption in a sector (0–0.95): licensing, bans, unions, incidents. Certification and arms races lower it.', src: 'research/16 §1A.2' },
  binding: { title: 'Binding constraint', body: 'What holds a sector back: capability (AI cannot do the tasks), cost, [[friction]], or diffusion (adoption still catching up).', src: 'research/16 §1A' },
  tiers: { title: 'Control tiers', body: 'How much autonomy AI has in a domain: tool (drafting), advisor (humans usually accept), on-the-loop (AI acts, human can veto), out-of-loop. Higher tiers count more toward [[leverage]].', src: 'research/16 §2.1' },
  entrenched: { title: 'Entrenched', body: 'Leverage ≥ 15%: a misaligned model can bias advice and protect itself.', src: 'research/16 §2.3' },
  indispensable: { title: 'Indispensable', body: 'Leverage ≥ 35%: shutting the model down costs a large share of GDP and triggers a crisis.', src: 'research/16 §2.3' },
  decisive: { title: 'Decisive', body: 'Leverage ≥ 60% plus enough robots or physical reach: a misaligned model could take over.', src: 'research/16 §2.3' },
  moonshot: { title: 'Science moonshot', body: 'Assign a share of compute to one world technology. Your internal model speeds its research and can open its capability gate early.', src: 'research/16 §3.1' },
  transitionFund: { title: 'Transition fund', body: 'Money per year for displaced workers: faster retraining (+0.1 per $10B/yr, up to +0.5), lower job anxiety, labour approval.', src: 'research/16 §1A.2' },
  wtech: { title: 'World technology', body: 'One of 29 world technologies (W01–W29). Discovered when the best accessible model passes its gate, then ramps in over years. Some boost growth; risk technologies raise catastrophe exposure.', src: 'research/16 §3' },
  gdpG: { title: 'GDP growth', body: 'Annual real growth. AI raises it through capex and automation, but it stays capped until about half of economic value is automated.', src: 'research/16 §4.2–4.3' },
  gini: { title: 'Gini', body: 'Income inequality (0–1). Rises as labour share falls and unemployment grows; transfers lower it.', src: 'research/16 §4.4' },
  dow: { title: 'Dow', body: 'Equity index: earnings × a valuation multiple that rises with hype and falls with fear.', src: 'research/16 §4.5' },
  aiOwnerShare: { title: 'AI-owner share', body: 'Share of income going to the owners of AI: lab revenue, the labour share lost to automation, and special-economic-zone output.', src: 'research/16 §4.4' },
  laborShare: { title: 'Labour share', body: 'Share of income paid to workers (starts at 56%). Falls as tasks are automated.', src: 'research/16 §1A.2' },
  displaced: { title: 'Displaced workers', body: 'People who lost jobs to automation and have not yet found new work. Retraining and new tasks shrink the pool.', src: 'research/16 §1A.2' },
  youthUnemp: { title: 'Youth unemployment', body: 'Unemployment of 22–25-year-olds. Firms cut entry-level hiring before layoffs, so it rises first.', src: 'research/16 §1A.2' },
  remoteWork: { title: 'Remote work automated', body: 'Automated share of remote-workable jobs (software, office, finance, legal, media).', src: 'research/16 §1A.1' },
  firmAdoption: { title: 'Firm adoption', body: 'Share of firms using AI in production, by employment.', src: 'research/16 §1A' },
  robots: { title: 'Robots', body: 'Robot stock in human-worker equivalents. Caps physical capability in the world, so physical sectors automate only as production ramps.', src: 'research/16 §1.5' },
  // ── R10: structure, limits and the remaining IA terms ──
  coreLoop: { title: 'Core loop', body: 'How your company works: [[team|teams]] → research ([[knowHow|know-how]], [[techTree|tree]]) → models → assurance ([[U|understanding]]) → [[product|products]] → customers → cash, which buys people and compute. The [[takeoffLoop|takeoff loop]]: internal agents take over more of the teams\' work.', src: 'STRUCTURE §2' },
  takeoffLoop: { title: 'Takeoff loop', body: 'Your best model, used inside the company, does more and more of the teams\' work: first engineering, then routine research, then frontier research ([[aiShareWork|AI share of the work]]). This is AI 2027\'s engine; the same model may be misaligned.', src: 'STRUCTURE §2; AI 2027' },
  limit: { title: 'Limit', body: 'A cap, floor or gate you can hit. Each is shown where it binds as a small ⊘ note (grey when it does not bind, amber or red when it does), with its rule and source on hover. The codex lists them all under Limits.', src: 'STRUCTURE R11; design/LIMITS.md' },
  diffusion: { title: 'Knowledge diffusion', body: 'Ideas leak: papers, talks, hires and open models. While the frontier leader\'s public model is ahead of your best model, its published work adds 2.0 × the gap to your [[knowHow|know-how]] per year. Only the simulated AI 2027 leader diffuses; in the frontier-leader start there is none.', src: 'research/18 §0.2 [D, fit]' },
  frontierMethods: { title: 'Frontier methods', body: 'After your [[sc|SC]] milestone, research speed is measured against a lab that runs automated AI research agents (experiments ×1.5) and latent reasoning (agents ×2.5), phased in over 100–280 days. Unlock Automated AI research agents and train a Neuralese base to keep pace. The same rule holds for every lab.', src: 'AI 2027 (Agent-3); V2-SPEC §9 #4' },
  designOffset: { title: 'Research boost', body: 'A model\'s coding and research-skill design offsets (from its blueprint) make it a better or worse research agent than its level suggests: up to ±0.5 years of research progress.', src: 'V2-SPEC §3.1.5' },
  staleness: { title: 'Staleness', body: 'Know-how your lab gained after a model\'s base started training is not in it. See [[behindAtFinish|behind at finish]]: a long base run finishes behind.', src: 'TECH-TREE §1.5' },
  moe: { title: 'Mixture of experts', body: 'A backbone that routes each token to a few expert sub-networks: cheaper to serve per unit of capability, at some training overhead.', src: 'TECH-TREE; research/12' },
  nativeMultimodal: { title: 'Native multimodal', body: 'A backbone trained on text, images, audio and video together. Raises agency and media domains and enables voice & vision features.', src: 'TECH-TREE; research/12' },
  hardenedGraders: { title: 'Hardened graders', body: 'RL graders and reward models built to resist gaming: lower reward-hacking pressure at a training-cost premium (cheap with AI-assisted oversight).', src: 'research/14' },
  constitution: { title: 'Constitution', body: 'A written set of principles used for AI feedback in preference training. Lowers sycophancy and persona-drift pressure.', src: 'Bai et al. 2022 (Constitutional AI)' },
  honestyTraining: { title: 'Honesty training', body: 'Post-training that rewards calibrated, non-deceptive answers. Lowers concealment and sycophancy pressure.', src: 'research/14' },
  antiScheming: { title: 'Anti-scheming training', body: 'Deliberative alignment against covert actions. Cuts scheming sharply but raises eval awareness the first time a lineage gets it.', src: 'Schoen et al. 2025 (OpenAI / Apollo Research)' },
  detector: { title: 'Detector', body: 'A safety tool that reads a trait (probes, SAEs, honeypots, CoT monitors). Its strength fades as capability outgrows it unless [[toolUpkeep|upkeep]] keeps it validated.', src: 'research/14' },
  unseen: { title: 'Unseen', body: 'A risk family your detectors barely read (mean clarity below 30%): its estimate is mostly prior, not evidence.', src: 'STRUCTURE §4.5' },
  estimateBand: { title: 'Estimate ± band', body: 'Hidden quantities are shown as your best estimate with a 90% band. The truth is revealed only at the end.', src: 'STRUCTURE R9' },
  releaseClearance: { title: 'Release clearance', body: 'A model may power an external product once it passes the evaluation policy ([[autoEvaluate|auto-evaluate]]) and no commitment in scope forbids it.', src: 'STRUCTURE §4.4' },
  agentTasks: { title: 'Agent tasks', body: 'Long autonomous tasks sold by the Agents product. It needs a model whose measured [[timeHorizon|time horizon]] reaches the task length.', src: 'research/16 §2; METR' },
  bestRivalProduct: { title: 'Best rival product', body: 'The rival product with the largest share of the same segment\'s spend. Other rivals are in the share tooltip.', src: 'STRUCTURE §4.4' },
  qualityBound: { title: 'Quality-bound', body: 'A better model would sell more: demand is limited by what the product\'s model can do. Lever: upgrade the model.', src: 'STRUCTURE §4.4' },
  priceBound: { title: 'Price-bound', body: 'A lower price tier would earn more: demand falls with price^−1.5. Lever: a cheaper tier.', src: 'STRUCTURE §4.4' },
  autoSplit: { title: 'Auto split', body: 'The research budget re-splits every day between experiments and agents to maximise research speed. Switch it to manual on Compute › Split.', src: 'research/13 §1.6' },
  verbSet: { title: 'One verb set', body: 'Every action is one of seven verbs: hire, research, design & train, launch / update, set a policy, make a deal, respond.', src: 'STRUCTURE R2' },
};

/** v1 entries (copied, any leftover canon sentence dropped) overlaid by the v2 entries. */
export const GLOSSARY_V2: Record<string, Term> = {
  ...Object.fromEntries(Object.entries(GLOSSARY).map(([k, t]) => [k, { ...t, body: t.body.replace(/\s*Canonical date:[^.]*\./g, '') }])),
  ...V2,
};
